// Path helpers for the non-door id-keyed content notes ("Door Notes and
// Map Hover Plan.md" Part B3's entity->note resolver). Doors already have
// their own `doorNotePathFor` in `doorNotes.ts` (Locks & Traps Content
// Plan territory, since doors also get auto-generated content); corridors
// only ever get a note on-demand (no physical flag drives automatic
// creation for them - see Architecture doc), so this module is just the
// bare path shape, same `Floor N/<Kind>s/<Kind> <id>.md` convention.
//
// Stairs share the same convention per Part B3 (`Floor N/Stairs/Stair
// <id>.md`) but click-to-open-note isn't wired up for stairs yet (no
// interactive hit-area exists on a drawn stair icon today - see
// floor2dView.ts's `drawStairIcon`), so no `stairNotePathFor` here until
// that's actually built.
//
// Rooms are the one entity this module deliberately doesn't cover - their
// notes are name-based (`Room <NN> - <Name>.md`, pre-existing convention),
// so resolving one is a prefix-match against real files in the floor's
// folder, not a path this module can build outright. See main.ts's
// `resolveRoomNoteFile`.

/**
 * Does a note's file name belong to room `roomId`? Matches the `Room <NN>`
 * convention with optional zero-padding and anything after a space:
 * "Room 8", "Room 08", "Room 08 - Lair" all match room 8; "Room 18" and
 * "Room 8x" don't. Pulled out of main.ts on 2026-10-10: the pattern was
 * built in a template literal there, which silently turned every `\s`
 * into a plain `s` ("^Rooms+0*8(?:s|$)"), so no room note was ever found.
 */
export function isRoomNoteName(basename: string, roomId: number): boolean {
  return new RegExp(String.raw`^Room\s+0*${roomId}(?:\s|$)`, "i").test(basename);
}

/** `Floor N/Corridors/Corridor <id>.md` - id-keyed, exact path, per Plan B3. `folder` mirrors `main.ts`'s `setupFilePathFor` convention (the dungeon's own folder with a trailing slash already applied, or `""` at vault root). */
export function corridorNotePathFor(folder: string, floorBasename: string, corridorId: number): string {
  return `${folder}${floorBasename}/Corridors/Corridor ${corridorId}.md`;
}

/**
 * Minimal stub note content for a corridor's first click-to-open (see
 * `main.ts`'s `openEntityNote`) - corridors have no physical flag to
 * drive automatic content generation the way flagged doors do
 * (`doorNotes.ts`'s `buildDoorNoteMarkdown`), so this is deliberately bare:
 * created once, on demand, and never rewritten or wiped afterward (unlike
 * `Doors/`, which `syncDoorNotes` wipes/rebuilds on every regenerate while
 * the floor isn't finalized - see "Door Notes and Map Hover Plan.md" Part
 * B3's "on-demand, not auto-generated" framing for corridors/stairs).
 */
export function buildCorridorStubMarkdown(corridorId: number): string {
  return [
    `Corridor ${corridorId}`,
    "",
    `Created by "Dungeon Cartographer" on first click - unlike door notes, this isn't auto-regenerated on "Generate Random Map" (corridors have no locked/trapped/stuck-style flag to drive that). Edit freely, anytime.`,
    "",
    "## Notes",
    "",
    "",
  ].join("\n");
}

/**
 * Stage-2 map hover (Part B1.2): turns a note's raw markdown into a short
 * plain-text excerpt safe to drop straight into `floor2dView.ts`'s
 * pre-line tooltip, alongside the stage-1 physical-only line. Strips this
 * plugin's own auto-generated boilerplate (the "Auto-generated by ..."
 * line in `doorNotes.ts`'s `buildDoorNoteMarkdown`, the "Created by ..."
 * line in `buildCorridorStubMarkdown` above, the id/connects/material
 * header line - already covered by the stage-1 physical line - and the
 * "---"/"## Notes" scaffolding around the free-text section) plus markdown
 * emphasis markers, joins whatever's left with " · ", and caps it to
 * `maxLength`.
 *
 * A flagged door's note keeps its generated Locked/Trapped/Stuck/Challenge
 * level lines (the whole point of stage 2), so this only comes back ""
 * for a note that's still pure boilerplate - an unedited corridor stub,
 * or a room note before anyone's added anything below its own scaffolding.
 * `setHoverNoteExcerpt` treats "" as "nothing to add", not "clear the
 * tooltip" - the stage-1 physical line stands on its own either way.
 */
export function noteHoverExcerpt(markdown: string, maxLength = 220): string {
  const skipPrefixes = [
    "Auto-generated by",
    'Created by "Dungeon Cartographer"',
    "_Hand-added detail",
  ];
  const kept: string[] = [];

  for (const rawLine of markdown.split("\n")) {
    const line = rawLine.trim();
    if (!line) continue;
    if (line === "---" || line === "## Notes") continue;
    if (/^Door\s+\d+\s+—/.test(line)) continue; // id/connects/material header - stage 1 already shows this
    if (/^Corridor\s+\d+$/.test(line)) continue; // corridor stub's own bare header line
    if (skipPrefixes.some((prefix) => line.startsWith(prefix))) continue;
    kept.push(line.replace(/\*\*/g, ""));
  }

  const text = kept.join(" · ");
  return text.length > maxLength ? `${text.slice(0, maxLength - 1)}…` : text;
}
